import React,{useEffect,useRef,useState} from 'react';
import {auth} from '../firebase/config';
import {capabilities,DeviceVoice} from './deviceVoice';
import {handleCommand,validateHubRows,MYSA_ROLES,type HubRow} from './voiceCore';
const endpoint='https://udecs-owner-hub.sksaharukhossain1996.workers.dev';
function isOwner(){const u=auth.currentUser;return !!u?.emailVerified&&['sksaharukhossain1996@gmail.com','ecommerceunickdigital@gmail.com'].includes(u.email||'');}
export function MysaManager(){
 const[owner,setOwner]=useState(isOwner()),[rows,setRows]=useState<HubRow[]>([]),[loading,setLoading]=useState(false),[feed,setFeed]=useState('No verified reports loaded.'),[text,setText]=useState(''),[reply,setReply]=useState('Bolo Boss. Type a command or use device-local voice in the Android build.'),[status,setStatus]=useState('Microphone off'),[lang,setLang]=useState('en-IN'),[voice,setVoice]=useState(capabilities());
 const engine=useRef<DeviceVoice|null>(null),rowsRef=useRef(rows),abort=useRef<AbortController|null>(null),generation=useRef(0);
 rowsRef.current=rows;
 useEffect(()=>{engine.current=new DeviceVoice(event=>{if(event.type==='result'){setText(event.text||'');setReply(handleCommand(event.text||'',rowsRef.current));setStatus('Microphone off. Transcript ready.');}else if(event.type==='error')setStatus(event.message||'Device voice failed. Type instead.');else setStatus(({ready:'Microphone off',listening:'Listening locally. Tap Stop to end.',stopped:'Microphone off',speaking:'Speaking using an offline voice',spoken:'Microphone off'} as any)[event.type]||'Microphone off');});const changed=()=>setVoice(capabilities());window.addEventListener('udecs-device-capabilities',changed);const unsub=auth.onAuthStateChanged(()=>{generation.current++;abort.current?.abort();engine.current?.stop();setRows([]);setText('');setReply('Sign-in changed. Reload verified reports.');setFeed('No verified reports loaded.');setOwner(isOwner());setLoading(false);});return()=>{generation.current++;abort.current?.abort();engine.current?.dispose();unsub();window.removeEventListener('udecs-device-capabilities',changed);};},[]);
 async function load(){if(!isOwner())return;const u=auth.currentUser!,uid=u.uid,run=++generation.current;abort.current?.abort();const controller=new AbortController();abort.current=controller;const timeout=setTimeout(()=>controller.abort(),12000);setLoading(true);setRows([]);setFeed('Checking private dated snapshots...');try{const token=await u.getIdToken();if(run!==generation.current)return;const res=await fetch(endpoint+'/v1/status',{headers:{Authorization:'Bearer '+token},cache:'no-store',signal:controller.signal});if(!res.ok)throw Error('Private feed unavailable.');const j=await res.json(),r=validateHubRows(j.records);if(run!==generation.current||auth.currentUser?.uid!==uid||!isOwner())return;setRows(r);setFeed(r.length?'Dated snapshots loaded. Refresh does not re-check the source.':'No reports published. Missing data is not zero.');}catch{if(run===generation.current)setFeed('Private feed unavailable. No current status claimed.');}finally{clearTimeout(timeout);if(run===generation.current)setLoading(false);}}
 const ask=(value=text)=>{engine.current?.stop();setReply(handleCommand(value,rows));};
 if(!owner)return <section className="mysa-manager"><h2>Mysa manager</h2><p>Verified owner sign-in required. No microphone or private report is opened.</p></section>;
 return <section className="mysa-manager"><style>{css}</style><header><p className="my-eyebrow">MYSA · DEVICE-LOCAL VOICE</p><h1>Talk to Mysa</h1><p>Read-only report assistant. Free device voice, not a cloud AI conversation.</p></header><div className="my-notice">Mic starts only when you tap Talk. No cloud voice fallback, background listening, customer sends, payments or order changes.</div><div className="my-grid"><article className="my-panel my-voice"><img style={{display:'block',margin:'0 auto'}} className="my-avatar" src="data:image/png;base64," alt="Mysa concept avatar"/><h2>Hi, I am MYSA</h2><p role="status" className="my-status">{status}</p><label>Voice language<select value={lang}onChange={e=>{engine.current?.stop();setLang(e.target.value);}}><option value="en-IN">English (India)</option><option value="hi-IN">Hindi</option></select></label><div className="my-controls"><button disabled={!voice.recognition}onClick={()=>{try{engine.current?.start(lang);}catch(e){setStatus((e as Error).message);}}}>Tap to talk</button><button onClick={()=>engine.current?.stop()}>Stop</button><button disabled={!voice.tts}onClick={()=>{try{engine.current?.speak(reply,lang);}catch(e){setStatus((e as Error).message);}}}>Read reply aloud</button></div><p className="my-small">{voice.message}</p><form onSubmit={e=>{e.preventDefault();ask();}}><label htmlFor="mysa-command">Transcript / typed command</label><textarea id="mysa-command" value={text}maxLength={500}onChange={e=>setText(e.target.value)}placeholder="Read orders report / stock status / help"/><button type="submit">Read report</button></form><div className="my-reply" aria-live="polite">{reply}</div></article><aside className="my-panel"><h2>Owner report feed</h2><p>{feed}</p><button disabled={loading}onClick={load}>{loading?'Checking...':'Refresh dated reports'}</button><p className="my-small">Only authenticated Hub snapshots. Source time is shown and spoken. Older than two hours is labeled older, not a current check.</p><div className="my-roles">{MYSA_ROLES.map((name,i)=>{const r=rows.find(x=>Number(x.roleId)===i+1);return <button key={name}onClick={()=>{setText('Read '+name+' report');ask('Read '+name+' report');}}><b>{name}</b><small>{r?r.state:'No report loaded'}</small></button>;})}</div>{rows.map(r=><div className="my-source"key={r.roleId}><b>{MYSA_ROLES[Number(r.roleId)-1]}</b><p>{r.summary}</p><small>Source checked {new Date(r.checkedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})} IST</small><p className="my-small">{Date.now()-Date.parse(r.checkedAt)>7200000?'Older snapshot. Not current status.':'Dated snapshot, not live activity.'}</p></div>)}</aside></div></section>;
}
const css=`.mysa-manager{background:#08150d;color:#d2f3dc;border:1px solid #36573e;border-radius:16px;padding:25px;font:15px/1.5 Arial,sans-serif}.mysa-manager *{box-sizing:border-box}.mysa-manager h1{font-size:32px;color:#a9ffc0;margin:5px 0}.mysa-manager h2{font-size:21px;color:#a9ffc0;margin:10px 0}.mysa-manager p{margin:9px 0}.my-eyebrow{font:12px monospace;color:#89c99d;letter-spacing:1.2px}.my-notice{border:1px solid #66824b;background:#1c2a1b;padding:13px;border-radius:12px;font-size:13px;margin:20px 0}.my-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:18px}.my-panel{padding:22px;background:#102319;border:1px solid #385e44;border-radius:16px}.my-voice{text-align:center}.my-avatar{width:115px;height:115px;object-fit:cover;border:3px solid #83e4a0;border-radius:50%}.my-status{background:#183722;color:#c8f7d2;padding:8px;border-radius:30px;font-size:13px}.mysa-manager button{font:inherit;border:1px solid #457854;border-radius:9px;background:#173824;color:#c4f9d3;padding:10px 13px;cursor:pointer}.mysa-manager button:disabled{opacity:.5;cursor:not-allowed}.my-controls{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:18px 0}.my-small{font-size:12px;color:#a8c4b0}.mysa-manager label{font-size:13px;display:block;text-align:left}.mysa-manager select{background:#13281b;color:#d2f3dc;border:1px solid #4e775b;border-radius:6px;padding:7px;margin-left:10px}.mysa-manager textarea{display:block;width:100%;min-height:100px;background:#08150d;color:#d2f3dc;border:1px solid #4e775b;border-radius:8px;margin:8px 0 10px;padding:12px;font:14px Arial,sans-serif}.my-reply{text-align:left;white-space:pre-wrap;background:#193322;border-left:3px solid #91d4a3;padding:15px;margin-top:18px}.my-roles{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:18px}.my-roles button{text-align:left;font-size:12px}.my-roles small{display:block;font-size:11px;color:#d0dba7;margin-top:4px}.my-source{border-top:1px solid #34513e;margin-top:12px;padding-top:12px}.my-source small{font-size:11px;color:#a8c4b0}@media(max-width:700px){.mysa-manager{padding:16px}.my-grid{grid-template-columns:1fr}.my-panel{padding:16px}.mysa-manager h1{font-size:27px}}`;
